export const GENERAL_SCHOLAR_YAML = "schema_version: 1\nversion: \"1.0.0\"\n\ndescription: >\n  Cross-disciplinary profile for general academic literature, research methodology, higher education, and scientific communication.\n\nconventions:\n  separator: \"/\"\n  canonical_tag_format: \"{namespace}/{value}\"\n  allow_unlisted_values: false\n  prefer_precision_over_recall: true\n  avoid_metadata_duplication: true\n  metadata_fields_not_to_tag:\n    - author\n    - journal\n    - year\n    - doi\n    - publisher\n    - institution\n  notes:\n    - \"Collections/folders organize projects; tags reflect intrinsic content.\"\n    - \"Role describes contribution style (empirical, theoretical, review, method).\"\n    - \"Topic describes substantive domain questions, phenomena, or theories.\"\n    - \"System describes the physical, biological, conceptual, or social entity investigated.\"\n    - \"Method describes specific investigative techniques, protocols, or models.\"\n    - \"Status and priority are human-managed workflow namespaces.\"\n\nclassifier:\n  semantic_namespaces:\n    - role\n    - topic\n    - system\n    - method\n  workflow_namespaces:\n    - status\n  human_only_namespaces:\n    - priority\n  rules:\n    - \"Never invent a tag not defined in this taxonomy.\"\n    - \"Do not tag a concept merely because it is mentioned in passing.\"\n    - \"Prefer the most specific applicable canonical tag without adding redundant synonyms.\"\n    - \"Do not infer priority or reading status from document content.\"\n    - \"Use aliases only for recognition and normalisation; always emit the canonical tag.\"\n\nrelationships: []\n\nnamespaces:\n\n  status:\n    description: \"Reading and processing workflow state.\"\n    kind: workflow\n    classifier_eligible: false\n    max_tags: 1\n    mutually_exclusive: true\n    user_managed:\n      - reading\n      - read\n      - processed\n    values:\n      needs-triage:\n        description: \"Item requires human review or candidate tags await confirmation.\"\n        aliases: [\"triage\", \"needs review\", \"needs-review\"]\n      to-read:\n        description: \"Item has been queued into the reading list.\"\n        aliases: [\"unread\", \"to read\", \"to_read\"]\n      reading:\n        description: \"Item is actively being read.\"\n      read:\n        description: \"Item has been read and understood.\"\n        aliases: [\"done\"]\n      processed:\n        description: \"Notes or knowledge have been extracted into broader research workflow.\"\n\n  priority:\n    description: \"User judgement about importance or urgency to revisit.\"\n    kind: judgement\n    classifier_eligible: false\n    max_tags: 2\n    values:\n      core:\n        description: \"Foundational reference essential to ongoing projects.\"\n        aliases: [\"essential\", \"seminal\", \"must-read\", \"foundational\"]\n      high:\n        description: \"Highly relevant paper containing important results or techniques.\"\n        aliases: [\"important\", \"key-reference\"]\n      revisit:\n        description: \"Contains specific derivations, tables, or parameters to revisit later.\"\n        aliases: [\"bookmark\", \"check-later\", \"reference-back\"]\n\n  role:\n    description: \"Contribution style or epistemic purpose the work serves in the literature.\"\n    kind: semantic\n    classifier_eligible: true\n    max_tags: 2\n    values:\n      review:\n        description: \"Synthesises an established body of literature rather than presenting only a single narrow result.\"\n        aliases: [\"review article\", \"survey\", \"overview\", \"systematic review\", \"meta-analysis\"]\n      empirical:\n        description: \"Presents primary empirical data, field/laboratory observations, or experimental measurements.\"\n        aliases: [\"experimental\", \"empirical study\", \"measurement\", \"observational study\"]\n      theoretical:\n        description: \"Develops formal analytical theory, mathematical derivations, or conceptual frameworks.\"\n        aliases: [\"theory\", \"analytical model\", \"conceptual framework\", \"formal derivation\"]\n      methodological:\n        description: \"Introduces or evaluates a new algorithm, experimental protocol, measurement tool, or analytical workflow.\"\n        aliases: [\"methodology\", \"algorithm development\", \"protocol\", \"new method\"]\n      computational:\n        description: \"Presents numerical simulations, scientific computing models, or computational software tools.\"\n        aliases: [\"simulation\", \"in silico\", \"numerical study\", \"computational model\"]\n      application:\n        description: \"Applies established methodologies to investigate a specific domain target or practical case study.\"\n        aliases: [\"case study\", \"applied study\", \"field application\"]\n      commentary:\n        description: \"Editorial, commentary, position paper, or perspective on field directions.\"\n        aliases: [\"perspective\", \"editorial\", \"position paper\", \"opinion\"]\n\n  topic:\n    description: \"Substantive domain phenomena, research questions, theories, or mechanisms.\"\n    kind: semantic\n    classifier_eligible: true\n    max_tags: 4\n    values:\n      research-design:\n        description: \"Methodology, experimental design, causal inference, and validity.\"\n        aliases: [\"methodology\", \"study design\", \"experimental design\"]\n      open-science:\n        description: \"Reproducibility, open data, preprints, preregistration, and open access.\"\n        aliases: [\"reproducibility\", \"replication\", \"open data\", \"preregistration\"]\n      scholarly-communication:\n        description: \"Peer review, scientometrics, academic publishing, and citation dynamics.\"\n        aliases: [\"scientometrics\", \"bibliometrics\", \"peer review\", \"publishing\"]\n      science-policy:\n        description: \"Research funding, science governance, societal impact, and technology policy.\"\n        aliases: [\"research funding\", \"research policy\", \"innovation policy\"]\n      research-ethics:\n        description: \"Research integrity, human subject protections, dual-use research, and ethical oversight.\"\n        aliases: [\"bioethics\", \"research integrity\", \"IRB\", \"academic ethics\"]\n      interdisciplinary-studies:\n        description: \"Cross-boundary research, synthesis frameworks, and convergent science.\"\n        aliases: [\"multidisciplinary\", \"transdisciplinary\", \"convergence\"]\n      higher-education:\n        description: \"Academic institutions, doctoral training, university administration, and pedagogy.\"\n        aliases: [\"academia\", \"university\", \"doctoral education\"]\n      data-infrastructure:\n        description: \"Research data management, FAIR principles, archives, and scholarly repositories.\"\n        aliases: [\"FAIR data\", \"data repositories\", \"research data\"]\n\n  system:\n    description: \"Physical, biological, social, or computational entity under primary study.\"\n    kind: semantic\n    classifier_eligible: true\n    max_tags: 3\n    values:\n      academic-institutions:\n        description: \"Universities, research institutes, colleges, and scholarly associations.\"\n        aliases: [\"university\", \"institute\", \"faculty\"]\n      scholarly-literature:\n        description: \"Journal articles, preprints, conference proceedings, and monographs.\"\n        aliases: [\"literature\", \"papers\", \"monographs\"]\n      research-community:\n        description: \"Scientists, scholarly networks, peer reviewers, and scientific disciplines.\"\n        aliases: [\"researchers\", \"scholars\", \"scientific network\"]\n      funding-bodies:\n        description: \"National funding agencies, philanthropic foundations, and grant schemes.\"\n        aliases: [\"grant agency\", \"funding agency\", \"NSF\", \"ERC\"]\n      research-infrastructure:\n        description: \"Shared computing facilities, research laboratories, and institutional repositories.\"\n        aliases: [\"facilities\", \"shared lab\", \"supercomputer\"]\n\n  method:\n    description: \"Investigative, computational, analytical, or experimental techniques applied.\"\n    kind: semantic\n    classifier_eligible: true\n    max_tags: 3\n    values:\n      experiment:\n        description: \"Controlled lab, field, or online experimental procedures.\"\n        aliases: [\"controlled trial\", \"lab experiment\", \"field experiment\"]\n      simulation:\n        description: \"Numerical, agent-based, or synthetic computational simulation.\"\n        aliases: [\"computational simulation\", \"agent-based model\"]\n      survey:\n        description: \"Questionnaires, stratified sampling, and cross-sectional survey instruments.\"\n        aliases: [\"questionnaire\", \"sample survey\", \"polling\"]\n      qualitative:\n        description: \"Interviews, focus groups, thematic analysis, and ethnographic fieldwork.\"\n        aliases: [\"thematic analysis\", \"interviews\", \"fieldwork\"]\n      literature-synthesis:\n        description: \"Systematic reviews, meta-analyses, and scoping reviews.\"\n        aliases: [\"meta-analysis\", \"systematic review\", \"scoping review\"]\n      quantitative-analysis:\n        description: \"Statistical regression, econometric estimation, and observational data analysis.\"\n        aliases: [\"regression\", \"multivariate analysis\", \"statistics\"]\n";

